<?php
function db(array $c):PDO{return new PDO('mysql:host='.$c['host'].';port='.(int)($c['port']??3306).';dbname='.$c['db'].';charset=utf8mb4',$c['user'],$c['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);}
function migrate(PDO $p):void{
$p->exec("CREATE TABLE IF NOT EXISTS users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('student','admin') NOT NULL DEFAULT 'student',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
foreach(['phone'=>"VARCHAR(25) NOT NULL DEFAULT ''",'status'=>"VARCHAR(20) NOT NULL DEFAULT 'active'",'verified'=>"TINYINT NOT NULL DEFAULT 0"] as $k=>$v){$q=$p->query("SHOW COLUMNS FROM users LIKE '$k'");if(!$q->fetch())$p->exec("ALTER TABLE users ADD COLUMN $k $v");}
$p->exec("CREATE TABLE IF NOT EXISTS applications(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(25) NOT NULL,program VARCHAR(100) NOT NULL,status ENUM('Bekliyor','Onaylandı','Reddedildi') NOT NULL DEFAULT 'Bekliyor',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$p->exec("CREATE TABLE IF NOT EXISTS records(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,program VARCHAR(100) NOT NULL,seconds DECIMAL(6,2) NOT NULL,note VARCHAR(500) NOT NULL DEFAULT '',recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$p->exec("CREATE TABLE IF NOT EXISTS rate_limits(bucket CHAR(64) PRIMARY KEY,hits INT UNSIGNED NOT NULL,expires_at INT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$p->exec("CREATE TABLE IF NOT EXISTS site_settings(id INT PRIMARY KEY,body LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$p->exec("CREATE TABLE IF NOT EXISTS site_items(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kind VARCHAR(20) NOT NULL,title VARCHAR(150) NOT NULL,subtitle VARCHAR(150) NOT NULL,body TEXT NOT NULL,photo VARCHAR(500) NOT NULL,active TINYINT NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$p->exec("CREATE TABLE IF NOT EXISTS nutrition(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,title VARCHAR(150) NOT NULL,body TEXT NOT NULL,starts DATE NOT NULL,ends DATE NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$p->exec("CREATE TABLE IF NOT EXISTS messages(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(25) NOT NULL,subject VARCHAR(150) NOT NULL,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'Yeni',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$p->exec("CREATE TABLE IF NOT EXISTS tokens(hash CHAR(64) PRIMARY KEY,user_id INT UNSIGNED NOT NULL,kind VARCHAR(20) NOT NULL,expires INT UNSIGNED NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$p->exec("CREATE TABLE IF NOT EXISTS student_questions(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,subject VARCHAR(150) NOT NULL,body TEXT NOT NULL,answer TEXT NULL,answered_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,answered_at DATETIME NULL,INDEX(user_id,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(answered_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
if(!$p->query('SELECT id FROM site_settings WHERE id=1')->fetch()){$s=json_decode(file_get_contents(__DIR__.'/seed.json'),true,512,JSON_THROW_ON_ERROR);$p->beginTransaction();try{$p->prepare('INSERT INTO site_settings VALUES(1,?)')->execute([json_encode($s['settings'],JSON_UNESCAPED_UNICODE)]);$q=$p->prepare('INSERT INTO site_items(kind,title,subtitle,body,photo,active,sort_order) VALUES(?,?,?,?,?,?,?)');foreach($s['items'] as $i)$q->execute([$i['kind'],$i['title'],$i['subtitle'],$i['body'],$i['photo'],$i['active'],$i['sort_order']??$i['id']]);$p->commit();}catch(Throwable $e){$p->rollBack();throw $e;}}
}
